// engine.hpp -- scalar full-width forwarding library (protocol 3).
//
// The legacy 64-bit interval / fixed-fanout baseline was replaced by exact
// 128-bit atlas compilation, FIDX image packing, packed lookup and the
// cache-budgeted layout planner.  Everything is scalar C++17 with no ISA
// extension beyond baseline x86-64.
#pragma once

#include <algorithm>
#include <array>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <map>
#include <queue>
#include <stdexcept>
#include <string>
#include <vector>

using u128 = unsigned __int128;
using u64 = unsigned long long;

// ---------------------------------------------------------------- utilities

inline std::string hex32(u128 x) {
    static const char* d = "0123456789abcdef";
    std::string s(32, '0');
    for (int i = 31; i >= 0; --i) {
        s[i] = d[unsigned(x & 15)];
        x >>= 4;
    }
    return s;
}

inline u128 parse32(const std::string& s) {
    if (s.size() != 32) throw std::runtime_error("key width");
    u128 v = 0;
    for (char c : s) {
        int d;
        if (c >= '0' && c <= '9') d = c - '0';
        else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
        else throw std::runtime_error("key digit");
        v = (v << 4) | unsigned(d);
    }
    return v;
}

inline void put_u16(char* p, unsigned v) {
    p[0] = char(v & 0xff); p[1] = char((v >> 8) & 0xff);
}
inline void put_u32(char* p, u64 v) {
    for (int i = 0; i < 4; ++i) p[i] = char((v >> (8 * i)) & 0xff);
}
inline void put_u64(char* p, u64 v) {
    for (int i = 0; i < 8; ++i) p[i] = char((v >> (8 * i)) & 0xff);
}
inline void put_u128(char* p, u128 v) {
    for (int i = 0; i < 16; ++i) p[i] = char(unsigned((v >> (8 * i)) & 0xff));
}
inline unsigned get_u16(const char* p) {
    return unsigned(unsigned char(p[0])) | (unsigned(unsigned char(p[1])) << 8);
}
inline u64 get_u32(const char* p) {
    u64 v = 0;
    for (int i = 0; i < 4; ++i) v |= u64(unsigned char(p[i])) << (8 * i);
    return v;
}
inline u64 get_u64(const char* p) {
    u64 v = 0;
    for (int i = 0; i < 8; ++i) v |= u64(unsigned char(p[i])) << (8 * i);
    return v;
}
inline u128 get_u128(const char* p) {
    u128 v = 0;
    for (int i = 0; i < 16; ++i) v |= u128(unsigned char(p[i])) << (8 * i);
    return v;
}

inline std::string hex_string(const std::string& raw) {
    static const char* d = "0123456789abcdef";
    std::string s(raw.size() * 2, '0');
    for (size_t i = 0; i < raw.size(); ++i) {
        s[2 * i] = d[(unsigned char(raw[i]) >> 4) & 15];
        s[2 * i + 1] = d[unsigned char(raw[i]) & 15];
    }
    return s;
}

// ------------------------------------------------------------- atlas stage

struct Route {
    u128 start;
    int length;
    int hop;          // -1 is never a route hop; used for null runs
    bool operator<(const Route& o) const {
        if (start != o.start) return start < o.start;
        return length < o.length;
    }
};

// Maximal forwarding runs: unique starts, coalesced equal next hops.
inline void compile_atlas(const std::vector<Route>& fib,
                          std::vector<u128>& starts,
                          std::vector<int>& hops) {
    const size_t n = fib.size();
    std::vector<u128> pts;
    std::vector<std::vector<int>> startAt, endAt;   // bucketed by sorted point
    pts.reserve(2 * n + 1);
    for (size_t i = 0; i < n; ++i) pts.push_back(fib[i].start);
    for (size_t i = 0; i < n; ++i) {
        if (fib[i].length == 0) continue;           // covers the whole domain
        u128 end = fib[i].start + ((u128)1 << (128 - fib[i].length));
        if (end == 0) continue;                     // end == 2^128
        pts.push_back(end);
    }
    pts.push_back(0);
    std::sort(pts.begin(), pts.end());
    pts.erase(std::unique(pts.begin(), pts.end()), pts.end());
    startAt.assign(n ? pts.size() : 1, {});
    endAt.assign(pts.size(), {});
    for (size_t i = 0; i < n; ++i) {
        size_t b = std::lower_bound(pts.begin(), pts.end(), fib[i].start) - pts.begin();
        startAt[b].push_back(int(i));
        if (fib[i].length == 0) continue;
        u128 end = fib[i].start + ((u128)1 << (128 - fib[i].length));
        if (end == 0) continue;
        b = std::lower_bound(pts.begin(), pts.end(), end) - pts.begin();
        endAt[b].push_back(int(i));
    }
    std::vector<char> alive(n, 0);
    // max-heap on prefix length, lazy deletion of dead routes
    std::priority_queue<std::pair<int, int>> heap;
    starts.clear();
    hops.clear();
    for (size_t b = 0; b < pts.size(); ++b) {
        for (int idx : endAt[b]) alive[idx] = 0;
        for (int idx : startAt[b]) {
            alive[idx] = 1;
            heap.push({fib[idx].length, idx});
        }
        while (!heap.empty() && !alive[heap.top().second]) heap.pop();
        int hop = heap.empty() ? -1 : fib[heap.top().second].hop;
        if (hops.empty() || hops.back() != hop) {
            starts.push_back(pts[b]);
            hops.push_back(hop);
        }
    }
}

// --------------------------------------------------------- image geometry

const int WIDTH[3] = {16, 8, 4};
const int LANES[3] = {4, 8, 16};

struct Node {
    int kind = 0;      // 0 internal, 1 leaf
    int mode = 0;
    int cached = 0;
    int lo = 0;
    int span = 0;
    std::vector<int> children;   // node row indices, left to right
};

inline int node_used(int kind, int b, int span, int mode) {
    int keys = (kind == 0) ? (b - 1) : span;
    int childbytes = (kind == 0) ? 4 * b : 0;
    return 32 + childbytes + keys * WIDTH[mode];
}
inline int node_alloc(int kind, int b, int span, int mode) {
    int used = node_used(kind, b, span, mode);
    return (used + 63) / 64 * 64;
}

struct Image {
    std::string bytes;
    std::vector<int> offsets;    // per node, in record order
    int hopoff = 0;
    int total = 0;
};

// Layout nodes are supplied in breadth-first order; node 0 is the root.
inline Image build_image(const std::vector<u128>& starts,
                         const std::vector<int>& hops,
                         const std::vector<Node>& nodes) {
    const int R = int(starts.size());
    if (R == 0 || nodes.empty()) throw std::runtime_error("empty image");
    Image img;
    img.offsets.assign(nodes.size(), 0);
    int cur = 64;
    for (size_t i = 0; i < nodes.size(); ++i) {
        const Node& n = nodes[i];
        if (n.lo < 0 || n.span <= 0 || n.lo + n.span > R)
            throw std::runtime_error("node range");
        img.offsets[i] = cur;
        cur += node_alloc(n.kind, int(n.children.size()), n.span, n.mode);
    }
    img.hopoff = cur;
    int hopbytes = (R * 4 + 63) / 64 * 64;
    img.total = img.hopoff + hopbytes;
    img.bytes.assign(size_t(img.total), '\0');
    char* p = &img.bytes[0];
    p[0] = 'F'; p[1] = 'I'; p[2] = 'D'; p[3] = 'X'; p[4] = 2;
    put_u32(p + 8, u64(R));
    put_u32(p + 12, u64(nodes.size()));
    put_u32(p + 16, u64(img.hopoff));
    put_u32(p + 20, u64(img.total));
    for (size_t i = 0; i < nodes.size(); ++i) {
        const Node& n = nodes[i];
        int off = img.offsets[i];
        int b = int(n.children.size());
        char* q = p + off;
        q[0] = char(n.kind);
        q[1] = char(n.mode);
        q[2] = char(n.cached);
        q[3] = 0;
        put_u16(q + 4, unsigned(n.lo));
        put_u16(q + 6, unsigned(n.span));
        put_u16(q + 8, unsigned(n.kind == 0 ? b : n.span));
        put_u16(q + 10, 0);
        put_u32(q + 12, u64(node_alloc(n.kind, b, n.span, n.mode)));
        u128 base = starts[n.lo];
        put_u128(q + 16, base);
        char* payload = q + 32;
        if (n.kind == 0) {
            for (int c = 0; c < b; ++c) {
                if (n.children[c] < 0 || size_t(n.children[c]) >= nodes.size())
                    throw std::runtime_error("child index");
                put_u32(payload + 4 * c, u64(img.offsets[n.children[c]]));
            }
            char* kp = payload + 4 * b;
            for (int c = 1; c < b; ++c) {
                u128 key = starts[nodes[n.children[c]].lo];
                if (n.mode == 0) put_u128(kp, key);
                else if (n.mode == 1) put_u64(kp, u64(key - base));
                else put_u32(kp, u64(key - base));
                kp += WIDTH[n.mode];
            }
        } else {
            char* kp = payload;
            for (int r = 0; r < n.span; ++r) {
                u128 key = starts[n.lo + r];
                if (n.mode == 0) put_u128(kp, key);
                else if (n.mode == 1) put_u64(kp, u64(key - base));
                else put_u32(kp, u64(key - base));
                kp += WIDTH[n.mode];
            }
        }
    }
    for (int r = 0; r < R; ++r) {
        u64 v = (hops[r] < 0) ? 0xffffffffu : u64(hops[r]);
        put_u32(p + img.hopoff + 4 * r, v);
    }
    return img;
}

// --------------------------------------------------------- packed lookup

struct Answer {
    int hop = 0;
    int run = 0;
    std::vector<int> path;
};

// Reads keys/children/hops straight out of the image bytes.
inline void lookup_image(const std::string& bytes, u128 addr, Answer& out) {
    if (bytes.size() < 128) throw std::runtime_error("short image");
    const char* p = bytes.data();
    int hopoff = int(get_u32(p + 16));
    int R = int(get_u32(p + 8));
    out.path.clear();
    int off = 64;
    while (true) {
        if (off + 32 > hopoff) throw std::runtime_error("node out of range");
        out.path.push_back(off);
        const char* q = p + off;
        int kind = unsigned char(q[0]);
        int mode = unsigned char(q[1]);
        u128 base = get_u128(q + 16);
        if (kind == 1) {
            int lo = int(get_u16(q + 4));
            int span = int(get_u16(q + 6));
            const char* kp = q + 32;
            int w = WIDTH[mode];
            // greatest stored start <= addr
            int lo_i = 0, hi_i = span;        // [lo_i, hi_i) candidates
            while (lo_i + 1 < hi_i) {
                int mid = (lo_i + hi_i) / 2;  // first index with key > addr
                u128 raw;
                if (mode == 0) raw = get_u128(kp + mid * w);
                else if (mode == 1) raw = u128(get_u64(kp + mid * w));
                else raw = u128(get_u32(kp + mid * w));
                u128 key = mode ? raw + base : raw;
                if (key <= addr) lo_i = mid + 1;
                else hi_i = mid;
            }
            // hmm: standard bisect_right semantics
            int idx = lo_i - 1;
            if (idx < 0) throw std::runtime_error("leaf predecessor");
            out.run = lo + idx;
            break;
        }
        int b = int(get_u16(q + 8));
        const char* cp = q + 32;
        const char* kp = cp + 4 * b;
        int w = WIDTH[mode];
        int lo_i = 0, hi_i = b - 1;
        while (lo_i < hi_i) {
            int mid = (lo_i + hi_i) / 2;
            u128 raw;
            if (mode == 0) raw = get_u128(kp + mid * w);
            else if (mode == 1) raw = u128(get_u64(kp + mid * w));
            else raw = u128(get_u32(kp + mid * w));
            u128 key = mode ? raw + base : raw;
            if (key <= addr) lo_i = mid + 1;
            else hi_i = mid;
        }
        off = int(get_u32(cp + 4 * lo_i));
    }
    if (out.run < 0 || out.run >= R) throw std::runtime_error("run range");
    u64 stored = get_u32(p + hopoff + 4 * out.run);
    out.hop = (stored == 0xffffffffu) ? -1 : int(stored);
}

// ------------------------------------------------------------ planner

struct BurstInput {
    int version = 0;
    long long repeat = 0;
    std::vector<int> runs;      // run index per address occurrence
};

struct VersionInput {
    int R = 0;
    std::vector<u128> starts;
    std::vector<int> hops;
};

struct CaseInput {
    int cache = 0;
    int hit = 1, miss = 1;
    int dec[3] = {0, 0, 0};
    std::vector<VersionInput> versions;
    std::vector<BurstInput> bursts;
};

// Breadth-first reorder of a depth-first built tree.
inline std::vector<Node> to_bfs(const std::vector<Node>& dfs) {
    std::vector<int> order;
    std::vector<int> queue;
    queue.push_back(0);
    size_t head = 0;
    while (head < queue.size()) {
        int cur = queue[head++];
        order.push_back(cur);
        for (int c : dfs[cur].children) queue.push_back(c);
    }
    if (order.size() != dfs.size()) throw std::runtime_error("unreachable node");
    std::vector<int> where(dfs.size(), -1);
    for (size_t i = 0; i < order.size(); ++i) where[order[i]] = int(i);
    std::vector<Node> out(dfs.size());
    for (size_t i = 0; i < order.size(); ++i) {
        out[i] = dfs[order[i]];
        for (int& c : out[i].children) c = where[c];
    }
    return out;
}

struct PlannedCase {
    std::vector<std::vector<Node>> nodes;    // per version
    std::vector<std::vector<int>> offsets;   // per version node offsets
    std::vector<std::string> images;         // per version hex
};

void plan_case(const CaseInput& ci, PlannedCase& out);
